import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CFuv5BrO.js";const c=JSON.parse('{"title":"Daily Use and Self-Report","description":"","frontmatter":{},"headers":[],"relativePath":"en/reference/daily-use.md","filePath":"en/reference/daily-use.md","lastUpdated":1795156772000}'),o={name:"en/reference/daily-use.md"};function n(r,e,d,l,h,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="daily-use-and-self-report" tabindex="-1">Daily Use and Self-Report <a class="header-anchor" href="#daily-use-and-self-report" aria-label="Permalink to &quot;Daily Use and Self-Report&quot;">​</a></h1><p>Hearth separates &quot;things that need a human&quot; from &quot;what the system is doing&quot;. In daily use you only need two places.</p><h2 id="the-needs-you-inbox" tabindex="-1">The &quot;Needs You&quot; inbox <a class="header-anchor" href="#the-needs-you-inbox" aria-label="Permalink to &quot;The &quot;Needs You&quot; inbox&quot;">​</a></h2><p><strong>Needs You</strong> (<code>/inbox</code>) in the sidebar only carries four signals:</p><ul><li>a task has been running for more than 30 minutes;</li><li>an approval has been waiting for more than 10 minutes;</li><li>a task stopped at its budget limit;</li><li>a task failed or failed recoverably.</li></ul><p>Each item can be marked read, snoozed (4 hours by default) or dismissed. The same task and kind do not repeat within 6 hours, and no new items are created between 22:00 and 08:00.</p><p>Notifications are not chat bubbles and are never sent to Feishu or email. They live in the local <code>data/supervision.json</code> file and are read by the web UI.</p><h2 id="yesterday-s-digest" tabindex="-1">Yesterday&#39;s digest <a class="header-anchor" href="#yesterday-s-digest" aria-label="Permalink to &quot;Yesterday&#39;s digest&quot;">​</a></h2><p>After 08:00, the first inbox request generates a digest for the previous day: completed, failed, waiting-approval and open counts, plus at most three suggestions. It uses the local date and never backfills older days.</p><h2 id="the-dogfood-report" tabindex="-1">The dogfood report <a class="header-anchor" href="#the-dogfood-report" aria-label="Permalink to &quot;The dogfood report&quot;">​</a></h2><p><code>npm run dogfood:report</code> reads the local event log for the last 7 days:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood:report</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood:report</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 30</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hearth-os</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reports/dogfood.md</span></span></code></pre></div><p>The report contains:</p><ul><li>tasks created, completed, failed and still active;</li><li>success rate (completed ÷ concluded) and first-attempt success;</li><li>attempts, turns, tool calls and input/output tokens;</li><li>approvals, approvals granted and rejected;</li><li>the most common failure messages and tasks that needed more than one attempt.</li></ul><p>These numbers describe real local use, not a public benchmark. For public evaluation use <code>npm run bench:suite</code> and <code>docs/evaluation/</code>. Reports default to <code>reports/</code>, which is local-only and not committed.</p><p>The runtime console (<code>/runtime</code>) shows the same 7-day summary for use without a terminal.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>The inbox does not decide how a task should be fixed; it reports facts and actions that need a human.</li><li>The dogfood report does not infer causes or blame the model or the user; failure messages are aggregated as recorded.</li><li>Data stays on this machine. Report files can contain task titles; review them before sharing.</li></ul>`,18)])])}const m=a(o,[["render",n]]);export{c as __pageData,m as default};
